sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.qr-card {
    max-width: 700px;
    margin: 40px auto;
    padding: 40px;
    background: white;
    border-radius: 12px;
    text-align: center;
    box-shadow: 0 4px 15px rgba(0,0,0,0.15);
}

.qr-card h1 {
    font-size: 32px;
}

.qr-card h2 {
    margin: 15px;
}

.qr-card p {
    font-size: 16px;
    margin: 10px;
}

.qr-code {
    width: 300px;
    height: 300px;
    display: block;
    margin: 25px auto;
}

sp_widget.script:
(function() {

    data.interview = null;
    data.error = '';

    var interviewId = $sp.getParameter('interview_id');

    if (!interviewId) {
        data.error = 'Interview ID is missing.';
        return;
    }

    var gr = new GlideRecord('x_snc_campus360_mock_interview');

    if (!gr.get(interviewId)) {
        data.error = 'Interview not found.';
        return;
    }

    data.interview = {
        sys_id: gr.getUniqueValue(),
        interview_id: gr.getValue('interview_id'),
        student: gr.student.getDisplayValue(),
        interview_date: gr.getDisplayValue('interview_date'),
        interview_type: gr.getDisplayValue('interview_type'),
        start_time: gr.getDisplayValue('start_time'),
        end_time: gr.getDisplayValue('end_time')
    };

    /*
     * THIS IS THE URL INSIDE THE QR CODE.
     *
     * IMPORTANT:
     * It points to student_attendance,
     * NOT qr_attendance.
     */

    var studentUrl =
        gs.getProperty('glide.servlet.uri') +
        'sp?id=student_attendance&interview_id=' +
        interviewId;

    data.qr_debug_url = studentUrl;

    data.qr_image_url =
        'https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=' +
        encodeURIComponent(studentUrl);

})();
